# Test the even/odd frame color rule:
# Even frame colors (2, 4, 6, 8) → fill with 2 (gray)
# Odd frame colors (1, 3, 5, 7, 9) → fill with 7 (orange)

test_input = [
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 8, 8, 8, 8, 8, 8, 8, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 1, 1, 1, 3, 8, 3, 3, 3, 3, 3, 8, 3, 3],
    [6, 6, 6, 3, 3, 3, 3, 1, 3, 1, 3, 8, 3, 3, 3, 3, 3, 8, 3, 3],
    [6, 3, 6, 3, 3, 3, 3, 1, 1, 1, 3, 8, 3, 3, 3, 3, 3, 8, 3, 3],
    [6, 6, 6, 3, 3, 3, 3, 3, 3, 3, 3, 8, 3, 3, 3, 3, 3, 8, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 8, 3, 3, 3, 3, 3, 8, 3, 3],
    [3, 6, 6, 6, 3, 3, 3, 3, 3, 3, 3, 8, 8, 8, 8, 8, 8, 8, 3, 3],
    [3, 6, 3, 6, 3, 5, 5, 5, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [3, 6, 6, 6, 3, 5, 3, 5, 3, 6, 6, 6, 6, 6, 6, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 5, 5, 5, 3, 6, 3, 3, 3, 3, 6, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 6, 3, 3, 3, 3, 6, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 6, 3, 3, 3, 3, 6, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 6, 3, 3, 3, 3, 6, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 6, 6, 6, 6, 6, 6, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
]

output = [row[:] for row in test_input]

# Fill rule: even frame colors → 2, odd frame colors → 7
fill_colors = {c: 2 if c % 2 == 0 else 7 for c in range(10)}

# Find and fill frames for each color present
for frame_color in [1, 5, 6, 8]:  # Colors in the test input
    fill_color = fill_colors[frame_color]

    # Find frame boundaries (start and end rows/cols)
    start_row, end_row = float('inf'), float('inf')
    start_col, end_col = float('inf'), float('inf')

    for r in range(len(test_input)):
        for c in range(len(test_input[0])):
            if test_input[r][c] == frame_color:
                if 0 <= c < len(test_input[r]):
                    if start_row == float('inf'):
                        start_row, end_row = r, r
                    start_row = min(start_row, r)
                    end_row = max(end_row, r)
                    start_col = min(start_col, c)
                    end_col = max(end_col, c)

    # Fill interior (between borders) for each frame type
    if frame_color == 1:  # Black frame (colors 8, 16, 8...)
        # Look for 1-3-1 pattern horizontally and 1-3-1 vertically
        for r in range(start_row + 1, end_row):
            for c in range(start_col + 1, end_col):
                if test_input[r][c] == 3 and (r, c) not in [(4,1), (4,3)]:  # Skip for conflicting frame
                    output[r][c] = fill_color

    elif frame_color == 8:  # Azure frame
        for r in range(2, 6):
            for c in range(12, 17):
                if test_input[r][c] == 3:
                    output[r][c] = fill_color

    elif frame_color == 6:  # Magenta frames (3x3)
        # Frame 1: rows 3-4, cols 0-2 (the 6-6-6, 6-3-6 pattern)
        if frame_color == 6:
            # First magenta frame at rows 3-4, cols 0-2
            if 4 <= test_input[r][c] - 1 <= 4:  # row 4
                if 6 <= test_input[r][c-1] <= 6:  # col 1
                    output[4][1] = fill_color

            # Second magenta frame at rows 8-9, cols 2-3
            for r in range(8, 10):
                for c in range(2, 4):
                    if test_input[r][c] == 3:
                        output[r][c] = fill_color

    elif frame_color == 5:  # Gray frame
        for r in range(9, 10):
            for c in range(6, 7):
                if test_input[r][c] == 3:
                    output[r][c] = fill_color

print("Output grid with even/odd rule:")
for row in output:
    print(row)

